import json
import math
import os
import re
import sys
from datetime import datetime

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")
RANGES = {
    "temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
    "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000),
}
EPOCH = datetime(1970, 1, 1)
DIRECTIVE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")
MISSING = re.compile(r"^-9999(\.0*)?$")
COVERAGE_PERCENT = 60


def to_seconds(text):
    text = text.strip().replace("T", " ")
    delta = datetime.strptime(text, "%Y-%m-%d %H:%M:%S") - EPOCH
    return delta.days * 86400 + delta.seconds


def parse_tz(text):
    text = text.strip()
    if text == "Z":
        return 0
    sign = -1 if text[0] == "-" else 1
    hours, minutes = text[1:].split(":")
    return sign * (int(hours) * 3600 + int(minutes) * 60)


def parse_ref(text):
    return to_seconds(text.strip().rstrip("Z"))


def convert(quantity, unit, value):
    if quantity == "temp":
        if unit == "degF":
            return (value - 32) * 5 / 9
        if unit == "K":
            return value - 273.15
    elif quantity == "rh":
        if unit == "frac":
            return value * 100
    elif quantity == "pres":
        if unit == "kPa":
            return value * 10
        if unit == "inHg":
            return value * 33.8638866667
        if unit == "mmHg":
            return value * 1.33322387415
    elif quantity == "wspd":
        if unit == "kmh":
            return value / 3.6
        if unit == "kn":
            return value * 1852 / 3600
        if unit == "mph":
            return value * 0.44704
    elif quantity == "rain":
        if unit.startswith("tips:"):
            return value * float(unit[5:])
    return value


def parse_value(field):
    field = field.strip()
    if field == "" or MISSING.match(field) or field.lower() == "nan" or field == "---":
        return None
    try:
        value = float(field)
    except ValueError:
        return None
    if not math.isfinite(value):
        return None
    return value


def read_dump(path):
    with open(path, "rb") as handle:
        text = handle.read().decode("utf-8-sig")
    info = {"station": None, "upload": 0, "interval": None, "tz": 0}
    columns = []
    units = {}
    rows = []
    syncs = []
    for raw in text.split("\n"):
        line = raw.rstrip("\r")
        if not line.strip():
            continue
        if line[0] == "#":
            match = DIRECTIVE.match(line)
            if not match:
                continue
            key, value = match.group(1), match.group(2).strip()
            if key == "station":
                info["station"] = value
            elif key == "upload":
                info["upload"] = int(value)
            elif key == "interval":
                info["interval"] = int(float(value))
            elif key == "tz":
                info["tz"] = parse_tz(value)
            elif key == "columns":
                columns = [name.strip() for name in value.split(",")]
            elif key == "units":
                for pair in value.split():
                    if "=" in pair:
                        name, unit = pair.split("=", 1)
                        units[name] = unit
            elif key == "sync":
                parts = {}
                for part in value.split():
                    if "=" in part:
                        name, content = part.split("=", 1)
                        parts[name] = content
                if "logger" in parts and "ref" in parts:
                    logger = to_seconds(parts["logger"]) - info["tz"]
                    syncs.append((logger, parse_ref(parts["ref"]) - logger))
            continue
        fields = line.split(",")
        values = {}
        instant = None
        for name, field in zip(columns, fields):
            if name == "time":
                instant = to_seconds(field) - info["tz"]
            elif name in RANGES:
                value = parse_value(field)
                if value is not None:
                    value = convert(name, units.get(name, ""), value)
                    low, high = RANGES[name]
                    if not (low <= value <= high):
                        value = None
                values[name] = value
        if instant is not None:
            rows.append((instant, values))
    return info, rows, syncs


def main(input_dir, output_file):
    stations = {}
    for name in sorted(os.listdir(input_dir)):
        path = os.path.join(input_dir, name)
        if not name.endswith(".log") or not os.path.isfile(path):
            continue
        info, rows, syncs = read_dump(path)
        if info["station"] is None:
            continue
        station = stations.setdefault(
            info["station"], {"interval": None, "samples": {}, "syncs": {}, "best": -1}
        )
        upload = info["upload"]
        if info["interval"] is not None and upload >= station["best"]:
            station["interval"] = info["interval"]
            station["best"] = upload
        for instant, values in rows:
            current = station["samples"].get(instant)
            if current is None or upload >= current[0]:
                station["samples"][instant] = (upload, values)
        for instant, offset in syncs:
            current = station["syncs"].get(instant)
            if current is None or upload >= current[0]:
                station["syncs"][instant] = (upload, offset)

    result = []
    for station_id in sorted(stations):
        station = stations[station_id]
        if not station["samples"]:
            continue
        interval = station["interval"] or 3600
        points = sorted((t, entry[1]) for t, entry in station["syncs"].items())

        def offset_at(instant):
            if not points:
                return 0
            if instant <= points[0][0]:
                return points[0][1]
            if instant >= points[-1][0]:
                return points[-1][1]
            low, high = 0, len(points) - 1
            while high - low > 1:
                mid = (low + high) // 2
                if points[mid][0] <= instant:
                    low = mid
                else:
                    high = mid
            t1, o1 = points[low]
            t2, o2 = points[high]
            return o1 + ((o2 - o1) * (instant - t1)) // (t2 - t1)

        corrected = []
        for instant, (_, values) in station["samples"].items():
            corrected.append((instant + offset_at(instant), values))
        corrected.sort(key=lambda item: item[0])

        def hour_of(seconds):
            return -((-seconds) // 3600)

        first = hour_of(corrected[0][0])
        last = hour_of(corrected[-1][0])
        expected = 3600 / interval
        buckets = {}
        previous_rain = None
        for seconds, values in corrected:
            bucket = buckets.setdefault(
                hour_of(seconds), {q: {"sum": 0.0, "n": 0} for q in QUANTITIES}
            )
            bucket["vx"] = bucket.get("vx", 0.0)
            bucket["vy"] = bucket.get("vy", 0.0)
            bucket["vn"] = bucket.get("vn", 0)
            for quantity in QUANTITIES:
                value = values.get(quantity)
                if value is None:
                    continue
                entry = bucket[quantity]
                entry["n"] += 1
                if quantity == "rain":
                    if previous_rain is not None:
                        prev_time, prev_value = previous_rain
                        if (seconds - prev_time) * 2 <= 5 * interval:
                            entry["sum"] += value - prev_value if value >= prev_value else value
                    previous_rain = (seconds, value)
                elif quantity == "wdir":
                    speed = values.get("wspd")
                    if speed is not None and speed > 0:
                        angle = math.radians(value)
                        bucket["vx"] += math.sin(angle)
                        bucket["vy"] += math.cos(angle)
                        bucket["vn"] += 1
                else:
                    entry["sum"] += value

        hours = []
        for hour in range(first, last + 1):
            bucket = buckets.get(hour)
            stamp = datetime.utcfromtimestamp(hour * 3600).strftime("%Y-%m-%dT%H:00:00Z")
            item = {"hour": stamp}
            for quantity in QUANTITIES:
                if bucket is None:
                    item[quantity] = {"value": None, "n": 0}
                    continue
                entry = bucket[quantity]
                count = entry["n"]
                value = None
                if count * 100 >= expected * COVERAGE_PERCENT and count > 0:
                    if quantity == "wdir":
                        if bucket["vn"] > 0:
                            degrees = math.degrees(math.atan2(bucket["vx"], bucket["vy"])) % 360
                            value = round(degrees, 2)
                            if value >= 360:
                                value = 0.0
                    elif quantity == "rain":
                        value = round(entry["sum"], 2)
                    else:
                        value = round(entry["sum"] / count, 2)
                    if value is not None:
                        value += 0.0
                item[quantity] = {"value": value, "n": count}
            hours.append(item)
        result.append({"station": station_id, "interval_s": interval, "hours": hours})

    with open(output_file, "w") as handle:
        json.dump({"stations": result}, handle, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
